using Microsoft.EntityFrameworkCore;using RutaCero.Domain.Imports;using RutaCero.Domain.ValueObjects;
namespace RutaCero.Infrastructure.Persistence;
internal static class StatementImportConfiguration
{
 public static void Configure(ModelBuilder b){var x=b.Entity<StatementImport>();x.ToTable("statement_imports");x.HasKey(v=>v.Id);x.Property(v=>v.Id).HasColumnName("id");x.Property(v=>v.UserId).HasColumnName("user_id");x.Property(v=>v.FinancialAccountId).HasColumnName("financial_account_id");x.Property(v=>v.OriginalFileName).HasColumnName("original_file_name");x.Property(v=>v.StoredFileName).HasColumnName("stored_file_name");x.Property(v=>v.ContentType).HasColumnName("content_type");x.Property(v=>v.Size).HasColumnName("size");x.Property(v=>v.Sha256).HasColumnName("sha256").HasConversion(v=>v.Value,v=>new ImportHash(v));x.Property(v=>v.StorageKey).HasColumnName("storage_path");x.Property(v=>v.Status).HasColumnName("status").HasConversion<string>();x.Property(v=>v.ExtractedCount).HasColumnName("extracted_count");x.Property(v=>v.UploadedAt).HasColumnName("uploaded_at");x.HasIndex(v=>new{v.UserId,v.Sha256}).IsUnique();Rows(b);}
 private static void Rows(ModelBuilder b){var x=b.Entity<StatementImportRow>();x.ToTable("statement_import_rows");x.HasKey(v=>v.Id);x.Property(v=>v.Id).HasColumnName("id");x.Property(v=>v.UserId).HasColumnName("user_id");x.Property(v=>v.StatementImportId).HasColumnName("statement_import_id");x.Property(v=>v.Fingerprint).HasColumnName("fingerprint");x.Property(v=>v.Date).HasColumnName("transaction_date");x.Property(v=>v.Description).HasColumnName("description");x.Ignore(v=>v.Amount);x.Property<decimal>("_amount").HasColumnName("amount").HasPrecision(18,2);x.Property<Currency>("_currency").HasColumnName("currency").HasConversion<string>();x.Property(v=>v.IsCredit).HasColumnName("is_credit");x.Property(v=>v.Status).HasColumnName("status").HasConversion<string>();x.Property(v=>v.CategoryId).HasColumnName("category_id");x.Property(v=>v.TransactionType).HasColumnName("transaction_type").HasConversion<string>();x.HasIndex(v=>new{v.UserId,v.Fingerprint});}
}
